@app.cell(hide_code=True)
def obs_data(FALLBACK, mo, pyoso_db_conn, to_records):
    # Pre-load the FULL observations table once: opening a slot modal must be a pure
    # in-memory lookup, never a network round-trip.
    try:
        _rows = to_records(
            mo.sql(
                """/* uptime-strips + drand-statuspage 2026-07-20; threshold join 2026-08-16.
                   Compliance is computed HERE, not stored: the thresholds table carries the bar as it
                   stood on each day, so a corrected threshold re-renders history honestly instead of
                   leaving old rows judged against a number nobody agreed to. */
                SELECT o.function_id,
                       o.observed_at,
                       o.metric,
                       o.observed_value,
                       t.threshold_op,
                       t.threshold_value,
                       t.source AS threshold_source,
                       CASE
                         /* observed_value lands as a DOUBLE, so comparing it to '' is a
                            TYPE_MISMATCH that 400s the whole query and drops the page into its
                            stale-JSON fallback. NULL is the only empty. */
                         WHEN o.observed_value IS NULL THEN 'indeterminate'
                         WHEN t.threshold_op IS NULL THEN 'unscored'
                         WHEN t.threshold_op = '>=' THEN
                           CASE WHEN CAST(o.observed_value AS DOUBLE) >= CAST(t.threshold_value AS DOUBLE)
                                THEN 'pass' ELSE 'fail' END
                         WHEN t.threshold_op = '<=' THEN
                           CASE WHEN CAST(o.observed_value AS DOUBLE) <= CAST(t.threshold_value AS DOUBLE)
                                THEN 'pass' ELSE 'fail' END
                         WHEN t.threshold_op = '>' THEN
                           CASE WHEN CAST(o.observed_value AS DOUBLE) > CAST(t.threshold_value AS DOUBLE)
                                THEN 'pass' ELSE 'fail' END
                         WHEN t.threshold_op = '<' THEN
                           CASE WHEN CAST(o.observed_value AS DOUBLE) < CAST(t.threshold_value AS DOUBLE)
                                THEN 'pass' ELSE 'fail' END
                         WHEN t.threshold_op = '==' THEN
                           CASE WHEN CAST(o.observed_value AS DOUBLE) = CAST(t.threshold_value AS DOUBLE)
                                THEN 'pass' ELSE 'fail' END
                         ELSE 'unscored'
                       END AS sla_outcome,
                       o.method
                FROM filecoin.filpgf_sla_observations.filpgf_sla_observations o
                LEFT JOIN filecoin.filpgf_sla_thresholds.filpgf_sla_thresholds t
                       ON t.observed_at = o.observed_at
                      AND t.team = o.team
                      AND t.function_id = o.function_id
                      AND t.metric = o.metric
                ORDER BY o.observed_at
                """,
                output=False,
                engine=pyoso_db_conn,
            )
        )
    except Exception:
        _rows = []
    if not _rows:
        _rows = FALLBACK.get("observations", [])
    OBS_BY_FID = {}
    for _o in _rows:
        if _o.get("observed_value") in (None, ""):
            continue
        OBS_BY_FID.setdefault(_o["function_id"], []).append(_o)
    return (OBS_BY_FID,)


@app.cell(hide_code=True)
def monitored_map(COVERAGE):
    # Every registry function (adopted + draft) from the embedded coverage payload:
    # function_id -> slot, team, metric, state. Backs the slot modals.
    FN_INFO = {}
    for _f in COVERAGE["functions"]:
        for _e in _f["entries"]:
            FN_INFO.setdefault(
                _e["function_id"],
                {
                    "slot": (_f["category"], _f["sub_category"]),
                    "team": _e["team"],
                    "metric": _e["metric"],
                    "state": _e["state"],
                    "host": _e["host"],
                    "origin": _e.get("origin", "oso"),
                },
            )

    # Which kernel (category, subcategory) slot each registry-monitored function sits in.
    MONITORED = {
        "randomness-beacon": ("Blockchain Core & Physical Storage", "Randomness"),
        "builtin-actors": ("Blockchain Core & Physical Storage", "VM & Programmability"),
        "network-uptime": ("Blockchain Core & Physical Storage", "Ledger & Consensus"),
        "forest-release-cadence": ("Blockchain Core & Physical Storage", "Ledger & Consensus"),
        "forest-snapshots": ("Blockchain Core & Physical Storage", "Mainnet Infrastructure"),
        "mainnet-block-explorer": ("UX/DX", "Explorers and Tooling"),
        "content-routing-ipni": ("Storage Market Middleware", "Content routing"),
        "calibnet-chain-liveness": ("Coordination & Hardening", "Testnets"),
    }
    return FN_INFO, MONITORED


@app.cell(hide_code=True)
def kernel_frame(COVERAGE, MONITORED, TIER_ORDER, req_rows, sla_rows):
    # Slot status precedence (worst-but-useful): a recent interruption (fail) wins; else
    # if anything is okay (pass) the slot is green; else amber (indeterminate / not-yet-
    # monitored / proposed draft all collapse to amber at display time).
    _rank = {"fail": 0, "pass": 1, "indeterminate": 2, "monitored": 3, "proposed": 4}
    _by_fid = {r["function_id"]: r for r in sla_rows}
    _slot_status = {}
    _slot_lines = {}

    def _light(key, status, line=None):
        _cur = _slot_status.get(key)
        if _cur is None or _rank.get(status, 9) < _rank.get(_cur, 9):
            _slot_status[key] = status
        if line:
            _slot_lines.setdefault(key, []).append(line)

    for _fid, _key in MONITORED.items():
        if _fid in _by_fid:
            _light(_key, _by_fid[_fid]["sla_outcome"])
        else:
            _light(_key, "monitored")
    for _f in COVERAGE["functions"]:
        _key = (_f["category"], _f["sub_category"])
        for _e in _f["entries"]:
            _v = _by_fid.get(_e["function_id"])
            _st = (
                _v["sla_outcome"]
                if _v
                else ("monitored" if _e["state"] == "adopted" else "proposed")
            )
            _tag = "" if _e.get("origin", "oso") == "oso" else f" ({_e.get('origin')})"
            _light(_key, _st, f"{_e['team']}: {_e['metric']}{_tag} [{_st}]")

    kernel_rows = []
    for _r in req_rows:
        _key = (_r["category"], _r["subcategory"])
        kernel_rows.append(
            {
                "tier": _r["priority"],
                "category": _r["category"],
                "subcategory": _r["subcategory"],
                "title": _r["title"],
                "steward": _r.get("steward") or "",
                "status": _slot_status.get(_key, "unmonitored"),
                "monitors": _slot_lines.get(_key, []),
            }
        )
    _idx = {t: i for i, t in enumerate(TIER_ORDER)}
    kernel_rows.sort(key=lambda r: _idx.get(r["tier"], 99))
    return (kernel_rows,)


