@app.cell(hide_code=True)
def kernel_board(
    ACCENT,
    BG1,
    BG2,
    CATEGORY_COLOR,
    FG,
    FGD,
    FGS,
    FONT,
    FONTH,
    LINE,
    MONO,
    OBS_BY_FID,
    SIGNAL,
    STATUS_COLOR,
    TIER_ORDER,
    COVERAGE,
    kernel_rows,
    mo,
    sla_rows,
):
    # The Kernel Health Board. Tiles are the ~17 (category, sub_category) kernel slots,
    # grouped in tier bands. Clicking a tile opens a MODAL (pure-CSS ":checked" reveal,
    # so it survives static HTML export) carrying the full metrics behind that slot:
    # every team x metric, current reading + SLA chip, and a proper inline-SVG line chart
    # of the metric's observed history. Inline SVG (explicit viewBox) is immune to the
    # width-0-in-hidden-pane gotcha and needs no plotly.js. See docs/kernel-board-redesign-design.md.
    _SOFT = {
        "pass": "#DCEAE6",
        "fail": "#F6E0DA",
        "indeterminate": "#F7E7D3",
        "monitored": "#DEE2F0",
        "proposed": "#E8E1F0",
        "unmonitored": "#EFECE4",
    }
    _LABEL = {
        "pass": "OK",
        "fail": "interruption",
        "indeterminate": "indeterminate",
        "unscored": "no agreed SLA",
        "monitored": "pending",
        "proposed": "pending",
        "unmonitored": "pending",
    }
    _OC = {
        "pass": "#16A34A",
        "fail": "#DC2626",
        "indeterminate": "#D97706",
        "unscored": "#64748B",
    }

    def _fmt(v):
        a = abs(v)
        if a >= 1e9:
            return f"{v / 1e9:.2f}B"
        if a >= 1e6:
            return f"{v / 1e6:.2f}M"
        if a >= 1e3:
            return f"{v / 1e3:.1f}k"
        if a >= 1:
            return f"{v:.4g}"
        return f"{v:.3g}"

    # leanroadmap-style coloured category-icon square with an inline (Feather-style) glyph.
    def _cat_icon(cat, size=34):
        _glyph = {
            "Blockchain Core & Physical Storage": (
                '<path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 '
                '1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/>'
                '<polyline points="3.27 6.96 12 12.01 20.73 6.96"/><line x1="12" y1="22.08" x2="12" y2="12"/>'
            ),
            "Coordination & Hardening": '<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/>',
            "Coordination & Incentives": (
                '<line x1="12" y1="1" x2="12" y2="23"/>'
                '<path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/>'
            ),
            "UX/DX": (
                '<path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 '
                '7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/>'
            ),
            "Storage Market Middleware": (
                '<circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/>'
                '<line x1="8.59" y1="13.51" x2="15.42" y2="17.49"/>'
                '<line x1="15.41" y1="6.51" x2="8.59" y2="10.49"/>'
            ),
        }.get(cat, '<circle cx="12" cy="12" r="9"/>')
        _g = int(size * 0.54)
        return (
            f'<span style="flex:none; width:{size}px; height:{size}px; border-radius:5px; '
            f'background:#F1F5F9; display:inline-flex; align-items:center; justify-content:center;">'
            f'<svg width="{_g}" height="{_g}" viewBox="0 0 24 24" fill="none" stroke="#334155" '
            f'stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{_glyph}</svg></span>'
        )

    def _linechart(pts, thr, op, title, outcome_last):
        # pts: obs dicts (time-ordered) with observed_at / observed_value / sla_outcome.
        _W, _H, _ml, _mr, _mt, _mb = 680, 240, 58, 18, 32, 40
        _pw, _ph = _W - _ml - _mr, _H - _mt - _mb
        _n = len(pts)
        _step = max(1, _n // 120)  # downsample very long series (tvl / daily txns ~365)
        _idx = list(range(0, _n, _step))
        if _idx[-1] != _n - 1:
            _idx.append(_n - 1)
        _sp = [pts[i] for i in _idx]
        _vals = [float(p["observed_value"]) for p in _sp]
        _m = len(_sp)
        _lo, _hi = min(_vals), max(_vals)
        if thr is not None and thr > 0:
            _lo, _hi = min(_lo, thr), max(_hi, thr)
        if _hi == _lo:
            _hi = _lo + (abs(_lo) or 1.0) * 0.1 + 1e-9
        _rng = _hi - _lo

        def _X(i):
            px = _ml + (i * _pw / (_m - 1) if _m > 1 else _pw / 2)
            return px

        def _Y(v):
            py = _mt + (1 - (v - _lo) / _rng) * _ph
            return py

        _p = [
            f'<svg class="kchart" viewBox="0 0 {_W} {_H}" '
            f'preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg">'
        ]
        _p.append(
            f'<text x="{_ml}" y="17" font-family="{FONT}" font-size="12" '
            f'font-weight="600" fill="{FGD}">{title}</text>'
        )
        for _f in (0.0, 0.5, 1.0):  # 3 y gridlines + labels
            _yv = _lo + _rng * _f
            _yy = _Y(_yv)
            _p.append(
                f'<line x1="{_ml}" y1="{_yy:.1f}" x2="{_W - _mr}" y2="{_yy:.1f}" '
                f'stroke="{LINE}" stroke-width="1"/>'
            )
            _p.append(
                f'<text x="{_ml - 7}" y="{_yy + 3:.1f}" text-anchor="end" '
                f'font-family="{FONT}" font-size="10" fill="{FGS}">{_fmt(_yv)}</text>'
            )
        if thr is not None and thr > 0:
            _ty = _Y(thr)
            _p.append(
                f'<line x1="{_ml}" y1="{_ty:.1f}" x2="{_W - _mr}" y2="{_ty:.1f}" '
                f'stroke="{SIGNAL}" stroke-width="1.2" stroke-dasharray="4 3" opacity=".8"/>'
            )
            _src = (_sp[-1].get("threshold_source") or "provisional") if _sp else "provisional"
            _srcmark = "" if _src == "signed-appendix" else "  (provisional)"
            _p.append(
                f'<text x="{_W - _mr}" y="{_ty - 4:.1f}" text-anchor="end" font-family="{FONT}" '
                f'font-size="9.5" fill="{SIGNAL}">SLA {op} {_fmt(thr)}{_srcmark}</text>'
            )
        _poly = " ".join(f"{_X(i):.1f},{_Y(v):.1f}" for i, v in enumerate(_vals))
        _p.append(
            f'<polyline points="{_poly}" fill="none" stroke="{ACCENT}" '
            f'stroke-width="2" stroke-linejoin="round"/>'
        )
        if _m <= 45:
            for i, _pt in enumerate(_sp):
                _c = _OC.get(_pt.get("sla_outcome") or "", ACCENT)
                _p.append(f'<circle cx="{_X(i):.1f}" cy="{_Y(_vals[i]):.1f}" r="2.4" fill="{_c}"/>')
        else:
            _c = _OC.get(outcome_last or "", ACCENT)
            _p.append(f'<circle cx="{_X(_m - 1):.1f}" cy="{_Y(_vals[-1]):.1f}" r="3.2" fill="{_c}"/>')
        _seen_lx = set()
        for _li in (0, _m // 2, _m - 1):  # x date labels: first / mid / last (deduped)
            if _li in _seen_lx:
                continue
            _seen_lx.add(_li)
            _d = str(_sp[_li].get("observed_at"))[:10]
            _anchor = "start" if _li == 0 else ("end" if _li == _m - 1 else "middle")
            _p.append(
                f'<text x="{_X(_li):.1f}" y="{_H - 14}" text-anchor="{_anchor}" '
                f'font-family="{FONT}" font-size="10" fill="{FGS}">{_d}</text>'
            )
        _p.append("</svg>")
        return "".join(_p)

    def _uptimestrip(pts, title):
        # Atlassian-style uptime bars: one bar per day, coloured by SLA outcome (green pass /
        # red interruption / amber indeterminate / grey no-reading). This is the public rendering
        # of the SLA the team agreed to in its manifest — the outcome series, over time.
        # Worst-of-day wins. `unscored` ranks below indeterminate: not knowing the bar is a
        # weaker statement than not getting a reading, and must not mask a genuine failure.
        _rk = {"fail": 3, "indeterminate": 2, "": 2, "unscored": 1.5, "pass": 1}
        _bd = {}
        for _p in pts:
            _d = str(_p.get("observed_at"))[:10]
            _o = _p.get("sla_outcome") or ""
            if _d not in _bd or _rk.get(_o, 2) > _rk.get(_bd.get(_d, ""), 2):
                _bd[_d] = _o
        _ds = sorted(_bd)[-90:]
        if not _ds:
            return ""
        # A day with no agreed bar is not a passing day and not a failing one — counting it
        # either way is a claim we cannot support, so the percentage is over scored days only.
        _scored = [d for d in _ds if _bd[d] in ("pass", "fail")]
        _npass = sum(1 for d in _scored if _bd[d] == "pass")
        _up = f"{100.0 * _npass / len(_scored):.1f}% uptime" if _scored else "—"
        _bars = "".join(
            f'<span title="{d}: {_bd[d] or "no reading"}" style="flex:1 1 0; min-width:2px; '
            f'height:22px; border-radius:1.5px; background:{_OC.get(_bd[d], "#CBD5E1")};"></span>'
            for d in _ds
        )
        return (
            f'<div style="display:flex; justify-content:space-between; font-family:{MONO}; '
            f'font-size:10px; color:{FGS}; margin:0 0 4px;"><span>uptime &middot; last {len(_ds)}d</span>'
            f'<span style="font-weight:600; color:{FGD};">{_up}</span></div>'
            f'<div style="display:flex; gap:1.5px; align-items:stretch;">{_bars}</div>'
            f'<div style="display:flex; justify-content:space-between; font-family:{MONO}; '
            f'font-size:9px; color:{FGS}; margin-top:3px;"><span>{_ds[0]}</span><span>{_ds[-1]}</span></div>'
        )

    # ---- assemble slots (COVERAGE-driven; kernel_rows = per-slot status + stewards) -----
    _by_fid = {r["function_id"]: r for r in sla_rows}
    _status_by_slot, _stew_by_slot = {}, {}
    for _r in kernel_rows:
        _slot = (_r["category"], _r["subcategory"])
        _status_by_slot[_slot] = _r["status"]
        for _sw in (_r.get("steward") or "").split(","):
            _sw = _sw.strip()
            if _sw:
                _lst = _stew_by_slot.setdefault(_slot, [])
                if _sw not in _lst:
                    _lst.append(_sw)

    _cov, _order, _slots = {}, [], {}
    for _tier in TIER_ORDER:
        for _f in COVERAGE["functions"]:
            if _f["tier"] != _tier:
                continue
            _slot = (_f["category"], _f["sub_category"])
            if _slot not in _slots:
                _order.append(_slot)
                _slots[_slot] = {
                    "tier": _f["tier"],
                    "category": _f["category"],
                    "subcat": _f["sub_category"],
                    "status": _status_by_slot.get(_slot, "unmonitored"),
                    "titles": [],
                    "stewards": _stew_by_slot.get(_slot, []),
                }
            _s = _slots[_slot]
            if _f["function"] not in _s["titles"]:
                _s["titles"].append(_f["function"])
            _d = _cov.setdefault(_slot, {})
            for _e in _f["entries"]:
                _d[(_e["function_id"], _e["team"], _e["metric"])] = _e

    # ---- render tiles (grid) + modals -------------------------------------------------
    _rules = [
        ".kboard>input[type=radio]{display:none;}",
        ".kgrid{margin:0;}",
        ".ktile{transition:border-color .12s;}",
        ".ktile:hover{border-color:#94A3B8;}",
        ".kmodal{display:none;position:fixed;inset:0;z-index:3000;}",
        ".kmodal-bg{position:absolute;inset:0;background:rgba(15,23,42,.55);}",
        ".kcard{position:relative;z-index:1;width:min(840px,94vw);max-height:88vh;overflow-y:auto;"
        "border-radius:6px;padding:24px 26px;background:" + BG1 + ";border:1px solid " + LINE + ";"
        "box-shadow:0 24px 64px rgba(15,23,42,.30);}",
        ".kclose{position:absolute;top:12px;right:18px;cursor:pointer;font-size:24px;line-height:1;"
        "color:" + FGS + ";text-decoration:none;}",
        ".kclose:hover{color:" + FG + ";}",
        ".kchart{width:100%;height:auto;display:block;}",
        ".kmcard{border:1px solid " + LINE + ";border-radius:4px;padding:14px 16px;"
        "margin-top:12px;background:#fff;}",
        ".kviz{background:" + BG2 + ";border-radius:4px;padding:11px 13px;margin-top:10px;}",
    ]
    _radios = ['<input type="radio" name="kslot" id="kslot-none" checked>']
    _modals, _slot_idx = [], {}

    # One modal per (category, sub_category) SLOT — sibling functions share it.
    for _i, _slot in enumerate(_order):
        _s = _slots[_slot]
        _st = _s["status"]
        _rid = f"kslot-{_i}"
        _slot_idx[_slot] = _i
        _radios.append(f'<input type="radio" name="kslot" id="{_rid}">')
        _entries = list(_cov.get(_slot, {}).values())

        # ---- modal body: one uniform metric CARD per team x metric ---------------------
        # Every card has the same frame (header: team/metric + origin + status chip; body:
        # a .kviz panel). The panel is a line chart when >=2 observations exist, otherwise a
        # matching stat panel (big current value) — so timeseries and snapshot metrics read
        # as the same kind of thing, never a chart next to a bare text line.
        _rows_html = []
        for _e in sorted(_entries, key=lambda e: (e["team"], e["metric"])):
            _fid = _e["function_id"]
            _v = _by_fid.get(_fid)
            # provenance badge only when it's noteworthy — most metrics are OSO-authored,
            # so a badge on every row is just noise; show it for Karma / external PRs.
            _ob = {"karma": ("Karma", "#7C3AED"), "external-pr": ("External PR", "#0D9488")}.get(
                _e.get("origin", "oso")
            )
            _badge = (
                f'<span title="source of this metric" style="font-family:{MONO}; color:{_ob[1]}; '
                f'border:1px solid {_ob[1]}; border-radius:16px; padding:1px 7px; font-size:9.5px; '
                f'margin-left:7px;">{_ob[0]}</span>'
                if _ob
                else ""
            )
            if _v:
                _out = _v["sla_outcome"]
                _clr = STATUS_COLOR.get(_out, FGS)
                _ov = _v["observed_value"]
                _ov_s = "n/a" if _ov in (None, "") else _fmt(float(_ov))
                _chip_txt = _LABEL.get(_out, _out)
                _valcap = (
                    f'<b style="color:{ACCENT};">{_ov_s}</b>'
                    f'<span style="color:{FGS};"> &middot; SLA {_v["threshold_op"]} {_v["threshold_value"]}</span>'
                )
            else:
                # no landed verdict yet -> amber "pending" (one of the three signals)
                _out = None
                _clr, _chip_txt = STATUS_COLOR["indeterminate"], "pending"
                _valcap = f'<span style="color:{FGS};">{_e.get("host", "")}</span>'
            _chip = (
                f'<span style="font-family:{MONO}; color:{_clr}; border:1px solid {_clr}; '
                f'border-radius:16px; padding:1px 9px; font-size:11px; white-space:nowrap;">{_chip_txt}</span>'
            )

            # richest series for this function_id (a fn often carries a 1-pt SLA metric AND
            # a dense backfilled operational series under a different metric name).
            _series, _bm = None, ""
            _obs = OBS_BY_FID.get(_fid, [])
            if _obs:
                _bym = {}
                for _o in _obs:
                    if _o.get("observed_value") in (None, ""):
                        continue
                    _bym.setdefault(_o["metric"], []).append(_o)
                if _bym:
                    _bm = max(_bym, key=lambda k: len(_bym[k]))
                    _series = _bym[_bm]
            _thr = (
                float(_v["threshold_value"])
                if _v and _v.get("threshold_value") not in (None, "")
                else None
            )
            _op = _v["threshold_op"] if _v else ""
            if _thr is None and _series:
                _lt = next(
                    (o for o in reversed(_series) if o.get("threshold_value") not in (None, "")),
                    None,
                )
                if _lt:
                    _thr = float(_lt["threshold_value"])
                    _op = _op or (_lt.get("threshold_op") or "")

            if _series and len(_series) >= 2:
                _viz = (
                    f'<div class="kviz">'
                    f'{_uptimestrip(_series, _bm)}'
                    f'<div style="font-family:{MONO}; font-size:11px; margin:10px 0 4px;">{_valcap}</div>'
                    f"{_linechart(_series, _thr, _op, _bm, _out or _series[-1].get('sla_outcome'))}</div>"
                )
            else:
                if _series:
                    _big = _fmt(float(_series[-1]["observed_value"]))
                    _note = (
                        f'one reading so far &middot; {str(_series[-1].get("observed_at"))[:10]} '
                        f"&mdash; the series builds as reviews run"
                    )
                elif _v and _v.get("observed_value") not in (None, ""):
                    _big = _fmt(float(_v["observed_value"]))
                    _note = "current reading &middot; the series builds from the next review"
                else:
                    _big = "&mdash;"
                    _note = "no readings yet"
                _viz = (
                    f'<div class="kviz" style="display:flex; align-items:center; gap:18px;">'
                    f'<div style="font-family:{FONT}; font-size:1.9rem; font-weight:600; '
                    f'color:{ACCENT}; line-height:1;">{_big}</div>'
                    f'<div style="font-family:{MONO}; font-size:11px; color:{FGS}; line-height:1.55;">'
                    f"{_valcap}<br>{_note}</div></div>"
                )

            _rows_html.append(
                f'<div class="kmcard">'
                f'<div style="display:flex; align-items:center; justify-content:space-between; '
                f'gap:10px; flex-wrap:wrap;">'
                f'<div style="font-family:{MONO}; font-size:12px; color:{FGD};">'
                f'<b style="color:{FG};">{_e["team"]}</b> &middot; {_e["metric"]}{_badge}</div>'
                f"{_chip}</div>"
                f"{_viz}</div>"
            )

        _stew = ", ".join(_s["stewards"]) if _s["stewards"] else "n/a"
        _hclr = STATUS_COLOR.get(_st, FGS)
        _modals.append(
            f'<div class="kmodal m-{_i}">'
            f'<label class="kmodal-bg" for="kslot-none"></label>'
            f'<div class="kcard">'
            f'<label class="kclose" for="kslot-none">&times;</label>'
            f'<div style="display:flex; align-items:center; gap:13px; padding-right:26px;">'
            f'{_cat_icon(_s["category"], 40)}'
            f'<div style="flex:1; min-width:0;">'
            f'<div style="display:flex; align-items:baseline; gap:10px; flex-wrap:wrap;">'
            f'<span style="font-family:{FONTH}; font-style:italic; font-size:1.55rem; color:{FG};">'
            f'{_s["subcat"]}</span>'
            f'<span style="font-family:{MONO}; color:{_hclr}; border:1px solid {_hclr}; '
            f'border-radius:16px; padding:1px 9px; font-size:11px; margin-left:auto;">'
            f'{_LABEL.get(_st, _st)}</span></div>'
            f'<div style="font-family:{MONO}; color:{FGS}; font-size:10.5px; letter-spacing:.05em; '
            f'text-transform:uppercase; margin-top:2px;">{_s["category"]} &middot; {_s["tier"]}</div>'
            f"</div></div>"
            f'<div style="color:{FGD}; font-size:12.5px; margin:12px 0 2px;">'
            f'<b style="color:{FG};">Kernel functions here:</b> {" &middot; ".join(_s["titles"])}</div>'
            f'<div style="font-family:{MONO}; color:{FGS}; font-size:11px;">steward: {_stew}</div>'
            + ("".join(_rows_html) if _rows_html else
               f'<div style="color:{FGS}; font-size:12px; padding-top:10px;">'
               f"No metric adopted for this function yet.</div>")
            + "</div></div>"
        )
        _rules.append(
            "#%s:checked ~ .kmodalwrap .m-%d{display:flex;align-items:center;justify-content:center;padding:20px;}"
            % (_rid, _i)
        )

    # ---- grid: one box PER kernel function (every function is represented; sibling
    # functions in a slot point at that slot's shared modal) ----------------------------
    _grid = []

    def _box(_f):
        _slot = (_f["category"], _f["sub_category"])
        _i = _slot_idx[_slot]
        _st = _slots[_slot]["status"]
        _dot = STATUS_COLOR.get(_st, FGS)
        _fe = list(_cov.get(_slot, {}).values())
        _teams = len({_e["team"] for _e in _fe})
        _metrics = len({(_e["function_id"], _e["metric"]) for _e in _fe})
        _count = (
            f"{_teams} team{'s' if _teams != 1 else ''} &middot; "
            f"{_metrics} metric{'s' if _metrics != 1 else ''}"
            if _fe
            else "no metric yet"
        )
        _fn = _f["function"]
        if len(_fn) > 74:
            _fn = _fn[:72] + "&hellip;"
        return (
            f'<label for="kslot-{_i}" class="ktile" style="'
            f"cursor:pointer; background:#fff; "
            f'border:1px solid {LINE}; border-radius:4px; padding:14px 15px; '
            f'display:flex; gap:12px; align-items:flex-start;">'
            f'{_cat_icon(_f["category"])}'
            f'<div style="min-width:0; flex:1;">'
            f'<div style="font-family:{MONO}; font-size:9px; letter-spacing:.1em; '
            f'text-transform:uppercase; color:{FGS}; margin-bottom:4px;">{_f["sub_category"]}</div>'
            f'<div style="display:flex; align-items:flex-start; gap:7px;">'
            f'<span style="font-family:{FONT}; font-weight:600; font-size:13.5px; color:{FG}; '
            f'line-height:1.3;">{_fn}</span>'
            f'<span style="width:8px; height:8px; border-radius:50%; background:{_dot}; '
            f'flex:none; margin-top:4px;"></span></div>'
            f'<div style="display:flex; align-items:center; justify-content:space-between; '
            f'margin-top:9px;">'
            f'<span style="font-family:{MONO}; font-size:10px; color:{FGS};">{_count}</span>'
            f'<span style="color:{FGS}; font-size:18px; line-height:1;">&rsaquo;</span></div>'
            f"</div></label>"
        )

    for _tier in TIER_ORDER:
        _tfns = [
            _f
            for _f in COVERAGE["functions"]
            if _f["tier"] == _tier and (_f["category"], _f["sub_category"]) in _slot_idx
        ]
        if not _tfns:
            continue
        _grid.append(
            f'<div style="font-family:{MONO}; font-size:11px; letter-spacing:.2em; '
            f"text-transform:uppercase; color:{FG}; font-weight:600; margin:22px 0 2px; "
            f'border-top:1px solid {LINE}; padding-top:15px;">{_tier}</div>'
        )
        _cats = []
        for _f in _tfns:  # categories in first-appearance order, functions grouped strictly
            if _f["category"] not in _cats:
                _cats.append(_f["category"])
        for _cat in _cats:
            _grid.append(
                f'<div style="font-family:{MONO}; font-size:10px; letter-spacing:.16em; '
                f'text-transform:uppercase; color:{FGS}; margin:14px 0 8px;">{_cat}</div>'
            )
            _grid.append(
                '<div style="display:grid; gap:11px; margin-bottom:4px; align-items:stretch; '
                'grid-template-columns:repeat(auto-fill, minmax(250px, 1fr));">'
            )
            for _f in [_g for _g in _tfns if _g["category"] == _cat]:
                _grid.append(_box(_f))
            _grid.append("</div>")

    _css = "<style>" + "".join(_rules) + "</style>"
    _html = (
        f'<div class="kboard" style="font-family:{FONT};">'
        + _css
        + "".join(_radios)
        + f'<div class="kgrid">{"".join(_grid)}</div>'
        + f'<div class="kmodalwrap">{"".join(_modals)}</div>'
        + "</div>"
    )
    mo.Html(_html)
    return


@app.cell(hide_code=True)
def slate_data(FALLBACK, mo, pyoso_db_conn, to_records):
    import re as _re

    # Committee-facing project labels (the warehouse team_name is often a person).
    _LABEL = {
        "APP-KOZT1PS1-T25XTE": "drand (Randamu)",
        "APP-P0UD8I92-78VVRM": "Forest (ChainSafe)",
        "APP-P3NAPR7O-TSQ67Q": "Curio (FilOz)",
        "APP-VQC3PIBY-G2UDZJ": "Infra Services (ChainSafe)",
        "APP-P706QNLF-NLQPG5": "Chain.Love",
        "APP-U5CX297Z-XKDQDZ": "Plumbline (calibnet)",
        "APP-ZGCSXHWL-8PJG01": "Beryx (Zondax)",
        "APP-J8CF3XJY-CG03HL": "Blockscout",
        "APP-RRMZE7XC-XAVG4W": "Goldsky",
        "APP-0QLIOMS2-JSK1EM": "Filecoin Data Portal",
        "APP-OFZ5ILTO-QC1XCM": "Filecoin Docs (FIL-B)",
        "APP-O66TN87V-3MDZFT": "IPNI (OIF)",
        "APP-WVTOW236-LUGH7Y": "Zondax Core Infra",
        "APP-ICVR43KL-H0P3K6": "Ankr",
        "APP-9PTCWEQL-HVKGV8": "FIL Ponto",
        "APP-Z1L7URG7-TJ3G5D": "USDFC (Secured Finance)",
        "APP-US5QDXQP-FOCBY4": "Pyth Network",
    }

    def _num(v):
        if v in (None, "", "nan") or str(v) == "nan":
            return None
        try:
            return float(v)
        except (TypeError, ValueError):
            return None

    def _parse_slate(rows):
        out = []
        for r in rows:
            # the note may carry ", committed $X" between working and ". Open:" (optional);
            # committed itself is read from the dedicated committed_usd field, not the note.
            m = _re.search(
                r"status=([^,]+), working \$(.*?)(?:, committed \$[\d,]+)?\. Open: (.*)",
                r.get("snapshot_note") or "",
            )
            status, working, open_item = (m.group(1), m.group(2), m.group(3)) if m else ("", "", "")
            base = working.split("+")[0]
            nums = [float(x) for x in _re.findall(r"(\d+(?:\.\d+)?)", base)]
            usd = (sum(nums) / len(nums) * (1000 if "k" in base.lower() else 1)) if nums else None
            out.append(
                {
                    "app_ref": r["app_ref"],
                    "team_name": _LABEL.get(r["app_ref"]) or r.get("team_name") or r["app_ref"],
                    "status": status,
                    "working": working,
                    "working_usd": usd,
                    # committed-till-December: the headline funding figure (Kernel-tab column)
                    "committed_usd": _num(r.get("committed_usd")),
                    "open_item": open_item,
                    "functions": r.get("functions") or "",
                }
            )
        # sort by the headline committed amount, working as tiebreaker
        return sorted(out, key=lambda x: (-(x["committed_usd"] or 0), -(x["working_usd"] or 0)))

    try:
        _rows = to_records(
            mo.sql(
                """/* committed-till-dec 2026-07-16 */
                WITH latest AS (
                    SELECT MAX(snapshot_date) AS d
                    FROM filecoin.funding_model_static.decisions
                )
                SELECT c.app_ref,
                       MAX(i.team_name) AS team_name,
                       MAX(c.note) AS snapshot_note,
                       MAX(c.amount_committed_usd) AS committed_usd,
                       MAX(f.functions) AS functions
                FROM filecoin.funding_model_static.decisions c
                LEFT JOIN filecoin.funding_model_static.applicant_identity i
                  ON i.app_ref = c.app_ref AND i.snapshot_date = c.snapshot_date
                LEFT JOIN (
                    SELECT ar.app_ref, ar.snapshot_date,
                           ARRAY_JOIN(ARRAY_AGG(r.title), ' | ') AS functions
                    FROM filecoin.funding_model_static.application_requirements ar
                    JOIN filecoin.funding_model_static.requirements r
                      ON r.requirement_id = ar.requirement_id
                     AND r.snapshot_date = ar.snapshot_date
                    GROUP BY ar.app_ref, ar.snapshot_date
                ) f ON f.app_ref = c.app_ref AND f.snapshot_date = c.snapshot_date
                WHERE c.event_id LIKE 'csnap-%'
                  AND c.snapshot_date = (SELECT d FROM latest)
                GROUP BY c.app_ref
                """,
                output=False,
                engine=pyoso_db_conn,
            )
        )
        slate_rows = _parse_slate(_rows)
        if not slate_rows:
            slate_rows = _parse_slate(FALLBACK.get("slate", []))
    except Exception:
        slate_rows = _parse_slate(FALLBACK.get("slate", []))
    return (slate_rows,)


@app.cell(hide_code=True)
def slate_section(ACCENT, BG1, BG2, COVERAGE, FG, FGD, FGS, FONT, FONTH, LINE, MONO, mo, slate_rows):
    _total = sum(r["committed_usd"] for r in slate_rows if r["committed_usd"])
    _covered = sum(1 for f in COVERAGE["functions"] if f["entries"])
    _live = sum(
        1
        for f in COVERAGE["functions"]
        if any(e["host"] != "fixture" for e in f["entries"])
    )
    _n_fn = len(COVERAGE["functions"]) or 29
    _tiles_data = [
        ("Batch 3 slate", f"{len(slate_rows)} projects"),
        ("Committed &middot; thru Dec", f"${_total / 1e6:.2f}M"),
        ("Kernel functions covered", f"{_covered}/{_n_fn}"),
        ("With live metrics", f"{_live}/{_n_fn}"),
    ]
    _MA = "#D97706"  # money-section accent (amber), echoing leanroadmap's per-section colours
    _tiles = "".join(
        f'<div style="flex:1 1 150px; background:{BG1}; border:1px solid {LINE}; '
        f'border-radius:4px; padding:16px 18px;">'
        f'<div style="font-family:{MONO}; font-size:10px; letter-spacing:.12em; '
        f'text-transform:uppercase; color:{FGS};">{label}</div>'
        f'<div style="font-family:{FONT}; font-size:1.7rem; font-weight:600; color:{_MA}; '
        f'margin-top:6px;">{val}</div></div>'
        for label, val in _tiles_data
    )
    _head = (
        f'<div id="money" style="font-family:{FONT}; color:{FG}; padding:6px 4px 4px; '
        f'margin-top:30px; scroll-margin-top:80px;">'
        f'<div style="font-family:{MONO}; font-size:10.5px; letter-spacing:.16em; '
        f'text-transform:uppercase; color:{_MA}; margin:0 0 7px;">View 2 &middot; ProPGF Batch 3</div>'
        f'<div style="display:flex; align-items:center; gap:13px; margin-bottom:8px;">'
        f'<div style="width:5px; height:30px; background:{_MA}; border-radius:3px;"></div>'
        f'<h2 style="font-family:{FONTH}; font-style:italic; font-size:2rem; font-weight:400; '
        f'margin:0; color:{FG};">ProPGF Funding</h2></div>'
        f'<div style="color:{FGD}; font-size:14px; margin:2px 0 14px;">'
        f"The committee's funding slate (latest snapshot): who's funded, at what number, for "
        f"which kernel functions. The headline figure is what's committed through December &mdash; "
        f"the amount contracted for the rest of the round. The working range and original ask are "
        f"shown alongside as negotiation context.</div>"
        f'<div style="display:flex; flex-wrap:wrap; gap:12px;">{_tiles}</div></div>'
    )
    mo.md(_head)
    return


@app.cell(hide_code=True)
def slate_chart(BG0, FG, FONT, LINE, SLATE_COLOR, go, slate_rows, static_plotly):
    _pts = [r for r in slate_rows if r["committed_usd"]]
    fig_slate = go.Figure()
    for _status in ("Advance", "Re-scope", "Unresolved"):
        _sub = [r for r in _pts if r["status"] == _status]
        if not _sub:
            continue
        fig_slate.add_trace(
            go.Bar(
                y=[r["team_name"][:34] for r in _sub],
                x=[r["committed_usd"] for r in _sub],
                orientation="h",
                name=_status,
                marker=dict(color=SLATE_COLOR.get(_status, "#94A3B8")),
                hovertext=[
                    f"<b>{r['team_name']}</b><br>committed ${r['committed_usd']:,.0f} through Dec"
                    f"<br>working {r['working']} ({r['status']})"
                    f"<br>{r['open_item']}"
                    for r in _sub
                ],
                hoverinfo="text",
            )
        )
    fig_slate.update_layout(
        paper_bgcolor=BG0,
        plot_bgcolor=BG0,
        font=dict(family=FONT, color=FG, size=12),
        title=dict(
            text="Committed through December by project",
            font=dict(color=FG, size=15),
        ),
        height=460,
        margin=dict(l=180, r=20, t=48, b=36),
        barmode="stack",
        legend=dict(orientation="h", y=1.08, x=1, xanchor="right"),
        yaxis=dict(autorange="reversed"),
    )
    fig_slate.update_xaxes(gridcolor=LINE, zeroline=False, title="USD (committed through Dec)")
    fig_slate.update_yaxes(gridcolor="rgba(0,0,0,0)")
    static_plotly(fig_slate)
    return


@app.cell(hide_code=True)
def slate_table(
    ACCENT, BG1, COVERAGE, FG, FGD, FGS, FONT, FONTH, LINE, MONO, STATUS_COLOR, SLATE_COLOR,
    mo, sla_rows, slate_rows,
):
    # Which registry team each funded project reports on. Clicking the project shows that
    # team's metrics and which of its reporting requirements are not OK.
    _APP_TEAM = {
        "APP-KOZT1PS1-T25XTE": "randamu",
        "APP-P0UD8I92-78VVRM": "chainsafe",
        "APP-P3NAPR7O-TSQ67Q": "filoz",
        "APP-VQC3PIBY-G2UDZJ": "chainsafe",
        "APP-P706QNLF-NLQPG5": "chain-love",
        "APP-U5CX297Z-XKDQDZ": "plumbline",
        "APP-ZGCSXHWL-8PJG01": "zondax",
        "APP-J8CF3XJY-CG03HL": "blockscout",
        "APP-RRMZE7XC-XAVG4W": "goldsky",
        "APP-0QLIOMS2-JSK1EM": "filecoin-data-portal",
        "APP-OFZ5ILTO-QC1XCM": "fil-b",
        "APP-O66TN87V-3MDZFT": "oif-ipni",
        "APP-WVTOW236-LUGH7Y": "zondax",
        "APP-ICVR43KL-H0P3K6": "ankr",
        "APP-9PTCWEQL-HVKGV8": "fil-ponto",
        "APP-Z1L7URG7-TJ3G5D": "secured-finance",
        "APP-US5QDXQP-FOCBY4": "pyth",
    }
    _C = {"OK": STATUS_COLOR["pass"], "interruption": STATUS_COLOR["fail"],
          "indeterminate": STATUS_COLOR["indeterminate"], "pending": STATUS_COLOR["indeterminate"]}
    _team_metrics = {}
    for _f in COVERAGE["functions"]:
        for _e in _f["entries"]:
            _team_metrics.setdefault(_e["team"], {})[(_e["function_id"], _e["metric"])] = dict(
                _e, _area=_f["sub_category"]
            )
    _by_fid = {r["function_id"]: r for r in sla_rows}

    def _sig(e):
        _v = _by_fid.get(e["function_id"])
        if _v:
            return (
                {"pass": "OK", "fail": "interruption", "indeterminate": "indeterminate"}.get(
                    _v["sla_outcome"], "indeterminate"
                ),
                _v,
            )
        return "pending", None

    def _pill(status):
        c = SLATE_COLOR.get(status, "#94A3B8")
        return (
            f'<span style="font-family:{MONO}; color:{c}; border:1px solid {c}; '
            f'border-radius:20px; padding:1px 9px; font-size:11px;">{status or "?"}</span>'
        )

    _radios = ['<input type="radio" name="proj" id="proj-none" checked>']
    _rules = [".pboard>input[type=radio]{display:none;}"]
    _modals, _rows_html = [], ""
    for _i, r in enumerate(slate_rows):
        _team = _APP_TEAM.get(r["app_ref"])
        _mets = sorted(_team_metrics.get(_team, {}).values(), key=lambda e: e["metric"])
        _labs = [_sig(e) for e in _mets]
        _nflag = sum(1 for lab, _ in _labs if lab != "OK")
        _dots = "".join(
            f'<span title="{lab}" style="display:inline-block; width:8px; height:8px; '
            f'border-radius:50%; background:{_C[lab]}; margin-right:3px;"></span>'
            for lab, _ in _labs
        )
        _name = r["team_name"][:38]
        _pid = f"proj-{_i}"
        if _mets:
            _radios.append(f'<input type="radio" name="proj" id="{_pid}">')
            _proj = (
                f'<label for="{_pid}" style="cursor:pointer; color:{ACCENT}; font-weight:600; '
                f'text-decoration:underline; text-underline-offset:2px;">{_name}</label>'
            )
            _flagc = STATUS_COLOR["fail"] if any(l == "interruption" for l, _ in _labs) else FGD
            _summary = (
                f'<span style="font-family:{MONO}; font-size:10px; color:{_flagc}; margin-left:4px;">'
                f"{_nflag} to check</span>"
                if _nflag
                else f'<span style="font-family:{MONO}; font-size:10px; color:{STATUS_COLOR["pass"]}; '
                f'margin-left:4px;">all OK</span>'
            )
            _report = _dots + _summary
        else:
            _proj = f'<span style="font-weight:600;">{_name}</span>'
            _report = f'<span style="color:{FGS};">&mdash;</span>'
        _cusd = f'${r["committed_usd"]:,.0f}' if r["committed_usd"] else "&mdash;"
        _rows_html += (
            f'<tr style="border-top:1px solid {LINE};">'
            f'<td style="padding:8px 10px; white-space:nowrap;">{_proj}</td>'
            f'<td style="padding:8px 10px;">{_pill(r["status"])}</td>'
            f'<td style="padding:8px 10px; font-family:{MONO}; white-space:nowrap; color:{FG}; '
            f'font-weight:600;">{_cusd}</td>'
            f'<td style="padding:8px 10px; font-family:{MONO}; white-space:nowrap; color:{FGS};">'
            f'{r["working"]}</td>'
            f'<td style="padding:8px 10px; white-space:nowrap;">{_report}</td>'
            f'<td style="padding:8px 10px; color:{FGS}; font-size:12px;">{r["open_item"][:100]}</td>'
            f"</tr>"
        )
        if _mets:
            _cards = ""
            for e, (lab, v) in zip(_mets, _labs):
                _val = ""
                if v and v.get("observed_value") not in (None, ""):
                    try:
                        _val = f'{float(v["observed_value"]):,.4g}'
                    except (TypeError, ValueError):
                        _val = str(v["observed_value"])
                _clr = _C[lab]
                _cards += (
                    f'<div class="kmcard" style="display:flex; align-items:center; '
                    f'justify-content:space-between; gap:10px;">'
                    f'<div style="min-width:0;">'
                    f'<div style="font-family:{MONO}; font-size:9px; letter-spacing:.1em; '
                    f'text-transform:uppercase; color:{FGS};">{e["_area"]}</div>'
                    f'<div style="font-family:{MONO}; font-size:12px; color:{FG};">{e["metric"]}</div></div>'
                    f'<div style="white-space:nowrap; font-family:{MONO}; font-size:12px;">'
                    + (f'<span style="color:{FG}; margin-right:8px;">{_val}</span>' if _val else "")
                    + f'<span style="color:{_clr}; border:1px solid {_clr}; border-radius:14px; '
                    f'padding:1px 8px; font-size:10.5px;">{lab}</span></div></div>'
                )
            _sub = f"{_nflag} to check" if _nflag else "all OK"
            _modals.append(
                f'<div class="kmodal pm-{_i}"><label class="kmodal-bg" for="proj-none"></label>'
                f'<div class="kcard"><label class="kclose" for="proj-none">&times;</label>'
                f'<div style="font-family:{FONTH}; font-style:italic; font-size:1.4rem; color:{FG}; '
                f'padding-right:26px;">{_name}</div>'
                f'<div style="font-family:{MONO}; font-size:11px; color:{FGS}; margin:2px 0 4px;">'
                f'reporting requirements &middot; {len(_mets)} metric{"s" if len(_mets) != 1 else ""} '
                f"&middot; {_sub}</div>{_cards}</div></div>"
            )
            _rules.append(
                "#%s:checked ~ .pmodalwrap .pm-%d{display:flex;align-items:center;justify-content:center;padding:20px;}"
                % (_pid, _i)
            )

    _table = (
        f'<div class="pboard" style="font-family:{FONT}; color:{FG};">'
        + "<style>" + "".join(_rules) + "</style>"
        + "".join(_radios)
        + f'<div class="ptable" style="background:{BG1}; border:1px solid {LINE}; '
        f'border-radius:4px; padding:6px 8px; margin-top:4px; overflow-x:auto;">'
        f'<table style="border-collapse:collapse; width:100%; font-size:13px;">'
        f'<thead><tr style="font-family:{MONO}; font-size:10px; letter-spacing:.12em; '
        f'text-transform:uppercase; color:{FGS}; text-align:left;">'
        f'<th style="padding:8px 10px;">project</th><th style="padding:8px 10px;">committee</th>'
        f'<th style="padding:8px 10px;">committed $ &middot; thru Dec</th>'
        f'<th style="padding:8px 10px;">working $</th>'
        f'<th style="padding:8px 10px;">reporting</th>'
        f'<th style="padding:8px 10px;">key open item</th></tr></thead>'
        f"<tbody>{_rows_html}</tbody></table></div>"
        + f'<div class="pmodalwrap">{"".join(_modals)}</div>'
        + "</div>"
    )
    # mo.Html (not mo.md): marimo's markdown table CSS would repaint rows white.
    mo.Html(_table)
    return


if __name__ == "__main__":
    app.run()
